python3 << 'EOF'
# Data from the tables (in thousands of dollars)
# June values (end of month) and September values for years 2000-2002

data = {
    2000: {
        'June': {
            'foreign_exchange_euro': 6634663,
            'foreign_exchange_yen': 8877769,
            'total_assets': 38750276
        },
        'Sept': {
            'foreign_exchange_euro': 6869302,
            'foreign_exchange_yen': 8733757,
            'total_assets': 37094883
        }
    },
    2001: {
        'June': {
            'foreign_exchange_euro': 6817884,
            'foreign_exchange_yen': 7595657,
            'total_assets': 34996129
        },
        'Sept': {
            'foreign_exchange_euro': 7373916,
            'foreign_exchange_yen': 7920048,
            'total_assets': 36353790
        }
    },
    2002: {
        'June': {
            'foreign_exchange_euro': 8198962,
            'foreign_exchange_yen': 7879571,
            'total_assets': 37619185
        },
        'Sept': {
            'foreign_exchange_euro': 8288205,
            'foreign_exchange_yen': 7757327,
            'total_assets': 37591058
        }
    }
}

# CPI-U data (BLS, not seasonally adjusted) - Need to verify these
# For March 2003, let's use 183.0 as reference
# Let me get the exact values

# Raw share calculations (before CPI adjustment)
print("=== Raw shares (not adjusted) ===")
for year in [2000, 2001, 2002]:
    for period in ['June', 'Sept']:
        fx = data[year][period]['foreign_exchange_euro'] + data[year][period]['foreign_exchange_yen']
        total = data[year][period]['total_assets']
        share = fx / total * 100
        print(f"{year} {period}: FX={fx}, Total={total}, Share={share:.4f}%")

print("\n=== With CPI adjustment to March 2003 dollars ===")

# CPI values (need to verify - let's look them up from BLS)
# Using CPI-U (Consumer Price Index for All Urban Consumers)
# Not seasonally adjusted - CUUR0000SA0
cpi = {
    2000: {'June': 172.2, 'Sept': 173.7},
    2001: {'June': 177.1, 'Sept': 178.8},
    2002: {'June': 179.9, 'Sept': 180.9},
    2003: {'March': 183.0}
}

cpi_march_2003 = 183.0

# Calculate CPI-adjusted values and shares
results = {}
for year in [2000, 2001, 2002]:
    results[year] = {}
    for period in ['June', 'Sept']:
        fx = data[year][period]['foreign_exchange_euro'] + data[year][period]['foreign_exchange_yen']
        total = data[year][period]['total_assets']

        # Adjust to March 2003 dollars
        cpi_current = cpi[year][period]
        fx_adj = fx * (cpi_march_2003 / cpi_current)
        total_adj = total * (cpi_march_2003 / cpi_current)

        share_adj = fx_adj / total_adj * 100
        results[year][period] = share_adj
        print(f"{year} {period}: CPI={cpi_current}, Adjusted Share={share_adj:.4f}%")

# Calculate averages
june_avg = (results[2000]['June'] + results[2001]['June'] + results[2002]['June']) / 3
sept_avg = (results[2000]['Sept'] + results[2001]['Sept'] + results[2002]['Sept']) / 3

print(f"\n=== Summary ===")
print(f"Average June share (2000-2002): {june_avg:.4f}%")
print(f"Average September share (2000-2002): {sept_avg:.4f}%")
print(f"Absolute difference: {abs(june_avg - sept_avg):.4f} percentage points")
EOF
